head.script:
// ===== Simple WebRTC 다대다 화상통화 구현 (P2P Mesh 방식) =====
// 모든 변수들은 화상통화 세션 동안 유지되며, 페이지 언로드 시 정리됨

/** @type {Map<string, RTCPeerConnection>} 사용자 ID별 P2P 연결 객체 매핑 */
let peerConnections = new Map();

/** @type {Map<string, Array>} 연결 전 수신된 ICE 후보들을 사용자별로 대기 저장 */
let pendingIceCandidates = new Map();

/** @type {MediaStream|null} 로컬 사용자의 카메라/마이크 스트림 (getUserMedia로 획득) */
let localStream = null;

/** @type {WebSocket|null} 시그널링 및 채팅용 WebSocket 연결 */
let chatSocket = null;

/** @type {boolean} 현재 화상통화 방 참가 상태 */
let isJoined = false;

/** @type {boolean} 로컬 오디오 음소거 상태 */
let isMuted = false;

/** @type {boolean} 로컬 비디오 비활성화 상태 */
let isVideoOff = false;

/** @type {Map<string, Object>} 원격 사용자들의 기본 정보 저장 (userId, userName, 기타) */
let remoteUserInfo = new Map();

/** @type {Map<string, MediaStream>} 사용자 ID별 원격 미디어 스트림 매핑 */
let remoteStreams = new Map();

// STUN/TURN 서버 설정
const iceServers = [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' },
    { urls: 'stun:stun2.l.google.com:19302' },
    // 무료 TURN 서버 추가
    {
        urls: 'turn:openrelay.metered.ca:80',
        username: 'openrelayproject',
        credential: 'openrelayproject'
    }
];

// ===== RTCPeerConnection 기본 설정 =====
/**
 * 모든 P2P 연결에 사용될 RTCPeerConnection 설정
 * @type {RTCConfiguration}
 */
const pcConfig = {
    iceServers: iceServers,
    iceCandidatePoolSize: 10
};

// ===== 사용자 식별 시스템 =====
/**
 * 고유 사용자 ID 생성 함수
 * 현재 시간과 랜덤 값을 조합하여 고유한 데스크톱 사용자 ID를 생성
 * @returns {string} 'user_timestamp_random' 형식의 고유 ID
 */
const generateUserId = () => {
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 1000);
    return `user_${timestamp}_${random}`;
};

// ===== 현재 사용자 정보 =====
/**
 * 현재 데스크톱 사용자 정보 객체
 * 세션에서 실제 사용자 정보를 로드할 때까지의 임시 값
 * dataObject 또는 URL 파라미터로 전달받은 projectId 사용
 * @type {Object}
 * @property {string} userId - 고유 사용자 ID
 * @property {string} userName - 사용자 표시명
 * @property {string} channelName - WebRTC 방 채널명
 */
let projectId = 'default';
let isFromPip = false;
try {
    // WebSquare popup의 dataObject에서 projectId 추출
    if ($p && $p.getParameter && $p.getParameter("projectInfo")) {
        const projectInfo = $p.getParameter("projectInfo");
        if (projectInfo && projectInfo.projectId) {
            projectId = projectInfo.projectId;
            isFromPip = projectInfo.fromPip === true;
        }
    }

    // 모바일에서 dataObject로 전달된 경우 처리
    if (projectId === 'default' && $p && $p.getParameter && $p.getParameter("dataObject")) {
        const dataObject = $p.getParameter("dataObject");
        if (dataObject && dataObject.projectInfo && dataObject.projectInfo.projectId) {
            projectId = dataObject.projectInfo.projectId;
        }
    }

    // 대안: URL parameter도 확인 (fallback)
    if (projectId === 'default') {
        const urlParams = new URLSearchParams(window.location.search);
        const urlProjectId = urlParams.get('project_id');
        if (urlProjectId) {
            projectId = urlProjectId;
        }
    }
} catch (e) {
}

let currentUser = {
    userId: generateUserId(),
    userName: "로딩중...",
    channelName: "webrtc-room-" + projectId
};

/**
 * 페이지 로드 시 초기화 함수
 * 프로젝트 ID 추출, 세션 사용자 정보 로드, WebRTC 시스템 초기화 등 수행
 * @returns {void}
 */
scwin.onpageload = function() {
    //카메라 촬영

    // HTTPS 체크
    if (location.protocol !== 'https:' && location.hostname !== 'localhost') {
        $c.win.alert("webRTC는 HTTPS 환경에서만 작동합니다.");
        return;
    }

    // 먼저 세션에서 사용자 정보 로드
    $p.executeSubmission("sbm_getUserInfo");

    // 데이터 초기화 (사용자 정보는 submission 완료 후 업데이트)
    dma_videoChat.set("channelName", currentUser.channelName);
    dma_videoChat.set("userId", currentUser.userId);
    dma_videoChat.set("userName", currentUser.userName);
    dma_videoChat.set("isJoined", "false");

    // WebSocket 초기화 (채팅용 - 그대로 유지)
    scwin.initializeChatWebSocket();

    // WebRTC 초기화는 사용자 정보 로드 완료 후 실행 (scwin.initializeWebRTCAfterUserInfo에서 처리)

    // 엔터키 이벤트 리스너 추가
    setTimeout(() => {
        const chatInput = document.getElementById("chatInput");
        if (chatInput) {
            chatInput.addEventListener('keydown', function(event) {
                if (event.keyCode === 13 || event.key === 'Enter') {
                    event.preventDefault();
                    scwin.sendChatMessage();
                    return false;
                }
            });

            chatInput.focus();
        } else {
        }

    }, 2000); // 충분한 로딩 시간 확보

    // PIP 이벤트 리스너 설정
    scwin.setupPipEventListeners();

    // PIP 모드 체크
    const urlParams = new URLSearchParams(window.location.search);
    if (urlParams.get('pipMode') === 'true') {
        scwin.setupPipMode();
    }
};

// 페이지 언로드 시 정리 작업
scwin.onpageunload = function() {

    try {
        // 1. WebRTC 스트림 정리
        if (scwin.localStream) {
            scwin.localStream.getTracks().forEach(function(track) {
                track.stop();
            });
            scwin.localStream = null;
        }

        // 2. 피어 연결 정리
        if (scwin.localConnection) {
            scwin.localConnection.close();
            scwin.localConnection = null;
        }

        // 3. 이벤트 리스너 정리
        if (typeof scwin.handleBeforeUnload === 'function') {
            window.removeEventListener('beforeunload', scwin.handleBeforeUnload);
        }
        if (typeof scwin.handleMessage === 'function') {
            window.removeEventListener('message', scwin.handleMessage);
        }

        // 4. 타이머 정리
        if (scwin.callTimer) {
            clearInterval(scwin.callTimer);
            scwin.callTimer = null;
        }

        // 5. 부모 창에 정리 완료 알림
        if (window.parent && window.parent !== window) {
            window.parent.postMessage({
                action: 'videoChatPageUnloaded',
                timestamp: Date.now()
            }, '*');
        }



    } catch (error) {

    }
};

// Simple WebRTC 초기화
/**
 * Simple WebRTC 시스템 초기화
 * HTTPS 환경 체크, WebRTC 지원 확인, 기본 설정 진행
 * @returns {void}
 * @throws {Error} HTTPS 환경 아니거나 WebRTC 미지원 시 에러
 */
scwin.initializeSimpleWebRTC = function() {
    try {

        // WebRTC 지원 확인
        if (!window.RTCPeerConnection) {
            throw new Error('RTCPeerConnection을 지원하지 않는 브라우저입니다');
        }

        // HTTPS 환경 체크
        const isHttps = window.location.protocol === 'https:';
        const isLocalhost = window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1';

        if (!isHttps && !isLocalhost) {
        } else if (isHttps) {
        } else {
        }



    } catch (error) {
    }
};

// 자동 화상통화 참가 (페이지 진입 시)
/**
 * 자동 화상통화 참가 (페이지 진입 시)
 * 로컬 미디어 스트림 획득, 비디오 표시, 방 참가 알림 전송
 * @async
 * @returns {Promise<void>} 자동 참가 완료 Promise
 * @throws {Error} 카메라/마이크 접근 권한 거부 또는 WebSocket 연결 실큀 시
 */
scwin.autoJoinCall = async function() {
    try {


        // 로컬 미디어 스트림 가져오기
        localStream = await navigator.mediaDevices.getUserMedia({
            video: { width: 1280, height: 720 },
            audio: true
        });

        // 로컬 비디오 표시 (기존 방식은 숨김)
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = localStream;
        }

        // 내 비디오를 그리드에 추가
        scwin.addMyVideoToGrid(localStream);

        // 화상통화 방 참가 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const joinRoomMessage = {
                type: 'join-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(joinRoomMessage));

        }

        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        scwin.updateControlButtons();





    } catch (error) {


        let errorMessage = "카메라/마이크 접근 권한이 필요합니다";
        if (error.name === 'NotAllowedError') {
            errorMessage = "카메라/마이크 권한을 허용해주세요.";
        } else if (error.message) {
            errorMessage = error.message;
        }



        // 오류 발생 시 기본 상태로 복원
        isJoined = false;
        dma_videoChat.set("isJoined", "false");
        scwin.updateControlButtons();
    }
};

// 화상통화 참가 (Simple WebRTC P2P 방식) - 수동 참가용
/**
 * 수동 화상통화 참가
 * 사용자의 명시적 참가 요청 시 로컬 미디어 획득 및 방 입장 처리
 * @async
 * @returns {Promise<void>} 화상통화 참가 완료 Promise
 * @throws {Error} 미디어 접근 권한 거부, WebSocket 연결 실큀, P2P 연결 실큀 시
 */
scwin.joinCall = async function() {
    try {
        scwin.showLoading("카메라와 마이크에 접근하는 중...");

        // 로컬 미디어 스트림 가져오기
        localStream = await navigator.mediaDevices.getUserMedia({
            video: { width: 1280, height: 720 },
            audio: true
        });

        // 로컬 비디오 표시 (기존 방식은 숨김)
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = localStream;
        }

        // 내 비디오를 그리드에 추가
        scwin.addMyVideoToGrid(localStream);

        // 화상통화 방 참가 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const joinRoomMessage = {
                type: 'join-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(joinRoomMessage));

        }

        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        scwin.updateControlButtons();
        scwin.hideLoading();





    } catch (error) {

        scwin.hideLoading();

        let errorMessage = "카메라/마이크 접근 권한이 필요합니다";
        if (error.name === 'NotAllowedError') {
            errorMessage = "카메라/마이크 권한을 허용해주세요.";
        } else if (error.message) {
            errorMessage = error.message;
        }

        $c.win.alert(errorMessage);

    }
};

// ===== Simple WebRTC 필수 함수들 =====

// WebRTC 시그널링 메시지 처리
function handleWebRTCMessage(message) {


    switch (message.type) {
        case 'user-joined':
            handleUserJoined(message.data);
            break;
        case 'offer':
            handleOffer(message.data);
            break;
        case 'answer':
            handleAnswer(message.data);
            break;
        case 'ice-candidate':
            handleIceCandidate(message.data);
            break;
        case 'user-left':
            handleUserLeft(message.data);
            break;
    }
}

// 새 사용자 참가 처리
async function handleUserJoined(data) {
    const { userId, userName } = data;
    if (userId === currentUser.userId) return;

    // 이미 연결된 사용자인지 확인
    if (peerConnections.has(userId)) {

                    return;
                }



    // P2P 연결 시작 (Offer 생성)
    await createPeerConnection(userId, userName, true);
}

// P2P 연결 생성
/**
 * P2P 연결 생성 및 관리
 * 특정 사용자와의 WebRTC PeerConnection 생성, 이벤트 리스너 설정, offer/answer 처리
 * @async
 * @param {string} userId - 연결할 상대방 사용자 ID
 * @param {string} userName - 연결할 상대방 사용자명
 * @param {boolean} isOfferer - offer 생성 주체 여부 (true: offer 생성, false: answer 대기)
 * @returns {Promise<RTCPeerConnection>} 생성된 PeerConnection 객체
 * @throws {Error} PeerConnection 생성/설정 실큀 시 에러
 */
async function createPeerConnection(userId, userName, isOfferer) {
    try {
        // ===== RTCPeerConnection 생성 및 기본 설정 =====
        const pc = new RTCPeerConnection(iceServers);
        peerConnections.set(userId, pc);

        // ===== 로컬 미디어 스트림 추가 =====
        // 내 카메라/마이크 스트림을 PeerConnection에 추가
        // 상대방이 ontrack 이벤트로 수신할 수 있도록 함
        if (localStream) {
            localStream.getTracks().forEach(track => {
                pc.addTrack(track, localStream);
            });
        }

        // ===== 원격 스트림 수신 처리 =====
        // 상대방의 미디어 스트림을 수신하면 자동으로 호출
        // event.streams[0]에 상대방의 비디오/오디오 트랙 포함
        pc.ontrack = (event) => {

            displayRemoteVideo(event.streams[0], userName, userId);
        };

        // ICE 후보 처리
        pc.onicecandidate = (event) => {
            if (event.candidate && chatSocket) {
                chatSocket.send(JSON.stringify({
                    type: 'ice-candidate',
                    channelName: currentUser.channelName,
                    targetUserId: userId,
                    iceCandidate: JSON.stringify(event.candidate),
                    userId: currentUser.userId,
                    userName: currentUser.userName,
                    timestamp: Date.now()
                }));
            }
        };

        // Offer 생성 및 전송
        if (isOfferer) {
            const offer = await pc.createOffer();
            await pc.setLocalDescription(offer);

            chatSocket.send(JSON.stringify({
                type: 'offer',
                channelName: currentUser.channelName,
                targetUserId: userId,
                sdp: JSON.stringify(offer),
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            }));
        }


        return pc; // PC 객체 반환

            } catch (error) {

        return null;
    }
}

// Offer 처리
/**
 * WebRTC Offer 수신 및 처리
 * 상대방으로부터 받은 SDP offer를 파싱하고 answer를 생성하여 응답
 * @async
 * @param {Object} data - offer 메시지 데이터
 * @param {string} data.userId - offer 발신자 사용자 ID
 * @param {string} data.userName - offer 발신자 사용자명
 * @param {string} data.sdp - JSON 문자열 형태의 SDP offer 정보
 * @returns {Promise<void>} offer 처리 완료 Promise
 * @throws {Error} SDP 파싱, PeerConnection 생성, answer 생성 실큀 시 에러
 */
async function handleOffer(data) {
    const { userId, userName, sdp } = data;


    const offer = JSON.parse(sdp);
    const pc = await createPeerConnection(userId, userName, false);

    if (!pc) {

        return;
    }

    await pc.setRemoteDescription(offer);

    // 대기 중인 ICE 후보들 처리
    await processPendingIceCandidates(userId);

    const answer = await pc.createAnswer();
    await pc.setLocalDescription(answer);

    chatSocket.send(JSON.stringify({
        type: 'answer',
        channelName: currentUser.channelName,
        targetUserId: userId,
        sdp: JSON.stringify(answer),
        userId: currentUser.userId,
        userName: currentUser.userName,
        timestamp: Date.now()
    }));
}

// Answer 처리
/**
 * WebRTC Answer 수신 및 처리
 * 상대방으로부터 받은 SDP answer를 로컬 PeerConnection에 설정
 * @async
 * @param {Object} data - answer 메시지 데이터
 * @param {string} data.userId - answer 발신자 사용자 ID
 * @param {string} data.sdp - JSON 문자열 형태의 SDP answer 정보
 * @returns {Promise<void>} answer 처리 완료 Promise
 * @throws {Error} SDP 파싱 또는 설정 실큀 시 에러
 */
async function handleAnswer(data) {
    const { userId, sdp } = data;
    const answer = JSON.parse(sdp);
    const pc = peerConnections.get(userId);
    if (pc) {
        await pc.setRemoteDescription(answer);

        // 대기 중인 ICE 후보들 처리
        await processPendingIceCandidates(userId);


    }
}

// ICE 후보 처리
/**
 * ICE Candidate 수신 및 처리
 * 상대방으로부터 받은 ICE candidate를 로컬 PeerConnection에 추가
 * 연결 전 수신된 candidate는 대기 큐에 저장 후 나중에 처리
 * @async
 * @param {Object} data - ICE candidate 메시지 데이터
 * @param {string} data.userId - candidate 발신자 사용자 ID
 * @param {string} data.iceCandidate - JSON 문자열 형태의 ICE candidate 정보
 * @returns {Promise<void>} ICE candidate 처리 완료 Promise
 * @throws {Error} candidate 파싱 또는 추가 실큀 시 에러
 */
async function handleIceCandidate(data) {
    try {
        const { userId, iceCandidate } = data;
        const candidate = JSON.parse(iceCandidate);
        const pc = peerConnections.get(userId);

        if (pc) {
            // Remote description이 설정되었는지 확인
            if (pc.remoteDescription) {
                await pc.addIceCandidate(candidate);

            } else {
                // Remote description이 없으면 대기 큐에 저장
                if (!pendingIceCandidates.has(userId)) {
                    pendingIceCandidates.set(userId, []);
                }
                pendingIceCandidates.get(userId).push(candidate);

            }
        } else {

        }
    } catch (error) {

    }
}

// 대기 중인 ICE 후보들 처리
async function processPendingIceCandidates(userId) {
    const pc = peerConnections.get(userId);
    const candidates = pendingIceCandidates.get(userId);

    if (pc && candidates && candidates.length > 0) {


        for (const candidate of candidates) {
            try {
                await pc.addIceCandidate(candidate);
    } catch (error) {

            }
        }

        pendingIceCandidates.delete(userId);

    }
}

// 사용자 나가기 처리
function handleUserLeft(data) {
    const { userId, userName } = data;
    const pc = peerConnections.get(userId);
    if (pc) {
        pc.close();
        peerConnections.delete(userId);
    }
    scwin.removeRemoteUser(userId);

}

// 원격 비디오 표시 (userId 추가로 정확한 매칭)
function displayRemoteVideo(stream, userName, userId) {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) {

            return;
        }

        // userId를 키로 스트림 저장
        if (userId) {
            remoteStreams.set(userId, stream);
        }

        // 기존 비디오 제거 (userName과 userId 둘 다 확인)
        const existingVideo = remoteVideosGrid.querySelector(`[data-username="${userName}"], [data-userid="${userId}"]`);
        if (existingVideo) {
            existingVideo.remove();

        }

        // 새 비디오 컨테이너 생성
        const videoContainer = document.createElement('div');
        videoContainer.className = 'remote-video-item';
        videoContainer.setAttribute('data-username', userName);
        if (userId) {
            videoContainer.setAttribute('data-userid', userId);
        }
        videoContainer.style.cssText = `
            position: relative;
            background: #000;
            border-radius: 8px;
            overflow: hidden;
            margin: 5px;
            min-width: 200px;
            min-height: 150px;
        `;

        // 비디오 엘리먼트 생성
        const video = document.createElement('video');
        video.autoplay = true;
        video.playsinline = true;
        video.muted = false;
        video.srcObject = stream;
        video.style.cssText = `
            width: 100%;
            height: 100%;
            object-fit: cover;
        `;

        // 사용자 이름 라벨 생성
        const label = document.createElement('div');
        label.className = 'remote-video-label';
        label.textContent = userName;
        label.style.cssText = `
            position: absolute;
            bottom: 8px;
            left: 8px;
            background: rgba(0,0,0,0.7);
            color: white;
            padding: 4px 8px;
            border-radius: 4px;
            font-size: 12px;
            z-index: 1;
        `;

        videoContainer.appendChild(video);
        videoContainer.appendChild(label);
        remoteVideosGrid.appendChild(videoContainer);



        // 비디오 로드 이벤트 처리
        video.onloadedmetadata = () => {

        };

        video.onerror = (error) => {

        };

    } catch (error) {

    }
}

// ===== 필수 함수들 (주석 밖에서 실행) =====

// WebSocket 채팅 시스템 초기화
scwin.initializeChatWebSocket = function() {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const port = window.location.port || (protocol === 'wss:' ? '443' : '80');

    // 여러 WebSocket URL 시도
    const wsUrls = [
        `${protocol}//${host}:${port}/InsWebApp/chat`,
        `ws://localhost:9093/InsWebApp/chat`,
        `wss://localhost:19443/InsWebApp/chat`
    ];

    let wsUrl = wsUrls[0];


    try {
        chatSocket = new WebSocket(wsUrl);

        chatSocket.onopen = function() {


            // 재연결 성공 시 시도 횟수 초기화
            if (window.wsReconnectAttempts && window.wsReconnectAttempts > 0) {

                window.wsReconnectAttempts = 0;
            }

            // 채널 참가
            const joinMessage = {
                type: 'join',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName
            };
            chatSocket.send(JSON.stringify(joinMessage));

            // 채팅 히스토리 요청
            setTimeout(() => {
                const historyMessage = {
                    type: 'history',
                    channelName: currentUser.channelName,
                    afterTimestamp: 0
                };
                chatSocket.send(JSON.stringify(historyMessage));

            }, 1000);
        };

        chatSocket.onmessage = function(event) {
            try {
                const data = JSON.parse(event.data);


                switch(data.type) {
                // 채팅 메시지 처리
                case 'message':
                    // 시스템 비디오 상태 메시지 처리
                    if (data.userName === 'SYSTEM_VIDEO_STATUS' && data.userId !== currentUser.userId) {
                        try {
                            const statusData = JSON.parse(data.message);
                            if (statusData.action === 'video-toggle') {
                                const remoteVideoContainer = document.querySelector(`[data-userid="${statusData.targetUserId}"] .remote-video-player`);
                                if (remoteVideoContainer) {
                                    const remoteVideo = remoteVideoContainer.querySelector('video');
                                    if (statusData.isVideoOff) {
                                        // 비디오 숨기고 꺼짐 메시지 표시
                                        if (remoteVideo) remoteVideo.style.display = 'none';
                                        let offMessage = remoteVideoContainer.querySelector('.camera-off-message');
                                        if (!offMessage) {
                                            offMessage = document.createElement('div');
                                            offMessage.className = 'camera-off-message';
                                            offMessage.style.cssText = `
                                                position: absolute;
                                                top: 50%;
                                                left: 50%;
                                                transform: translate(-50%, -50%);
                                                color: white;
                                                font-size: 18px;
                                                font-weight: bold;
                                                text-align: center;
                                                background: rgba(0,0,0,0.7);
                                                padding: 10px;
                                                border-radius: 8px;
                                                z-index: 10;
                                            `;
                                            offMessage.textContent = '카메라 꺼짐';
                                            remoteVideoContainer.appendChild(offMessage);
                                        }
                                    } else {
                                        // 비디오 표시하고 꺼짐 메시지 제거
                                        if (remoteVideo) remoteVideo.style.display = 'block';
                                        const offMessage = remoteVideoContainer.querySelector('.camera-off-message');
                                        if (offMessage) offMessage.remove();
                                    }
                                }

                            }
                        } catch (e) {

                        }
                    } else if (data.userName === 'SYSTEM_AUDIO_STATUS' && data.userId !== currentUser.userId) {
                        // 시스템 음소거 상태 메시지 처리
                        try {
                            const statusData = JSON.parse(data.message);
                            if (statusData.action === 'audio-toggle') {
                                const remoteUserName = document.querySelector(`[data-userid="${statusData.targetUserId}"] .remote-user-name`);
                                if (remoteUserName) {
                                    const userInfo = remoteUserInfo.get(statusData.targetUserId);
                                    const userName = userInfo ? userInfo.userName : statusData.targetUserName;

                                    if (statusData.isMuted) {
                                        remoteUserName.style.background = '#dc3545';
                                        remoteUserName.textContent = `${userName} - 음소거`;
                                    } else {
                                        remoteUserName.style.background = '#444';
                                        remoteUserName.textContent = userName;
                                    }
                                }

                            }
                        } catch (e) {

                        }
                    } else if (data.userId !== currentUser.userId && data.userName !== 'SYSTEM_VIDEO_STATUS' && data.userName !== 'SYSTEM_AUDIO_STATUS') {
                        // 일반 채팅 메시지
                        scwin.addChatMessage(data.userName, data.message, false, data.messageId, data.timestamp);

                    } else {

                    }
                    break;

                case 'history':
                    if (data.messages && data.messages.length > 0) {


                        // 웹스퀘어 데이터리스트 초기화
                        dlt_chatMessages.removeAll();
                        if (window.addedMessageIds) {
                            window.addedMessageIds.clear();
                        }

                        // 화면 채팅 메시지 초기화
                        const chatMessages = document.getElementById("chatMessages");
                        if (chatMessages) {
                            chatMessages.innerHTML = "";
                        }

                        data.messages.forEach(msg => {
                            const isOwn = msg.userId === currentUser.userId;
                            const msgId = msg.messageId || `history_${msg.userId}_${msg.timestamp}`;
                            scwin.addChatMessage(msg.userName, msg.message, isOwn, msgId, msg.timestamp);
                        });


                    } else {

                    }
                    break;

                case 'existing-users':


                    // 기존 사용자 정보 저장
                    if (data.userInfos) {
                        data.userInfos.forEach(user => {
                            remoteUserInfo.set(user.userId, user);

                        });
                    }
                    break;

                case 'user-joined':


                    // 새 사용자 정보 저장
                    if (data.userId && data.userName) {
                        remoteUserInfo.set(data.userId, {
                            userId: data.userId,
                            userName: data.userName
                        });

                    }

                    // Simple WebRTC P2P 연결 시작
                    if (isJoined) {
                        handleUserJoined(data);
                    }

                    // 미니 PIP가 활성화된 상태라면 업데이트 (지연 처리)
                    if (isMiniPipActive) {
                        setTimeout(() => {
                            scwin.updateMiniPIP();

                        }, 1000); // 비디오 연결 완료 후 업데이트
                    }
                    break;

                case 'user-left':


                    if (data.userId) {
                        remoteUserInfo.delete(data.userId);

                    }

                    // Simple WebRTC P2P 연결 해제
                    handleUserLeft(data);

                    // 미니 PIP가 활성화된 상태라면 업데이트
                    if (isMiniPipActive) {
                        setTimeout(() => {
                            scwin.updateMiniPIP();

                        }, 500); // 약간의 지연 후 업데이트
                    }
                    break;

                // Simple WebRTC 시그널링 메시지 처리
                case 'offer':
                    if (isJoined) {
                        handleOffer(data);
                    }
                    break;

                case 'answer':
                    if (isJoined) {
                        handleAnswer(data);
                    }
                    break;

                case 'ice-candidate':
                    if (isJoined) {
                        handleIceCandidate(data);
                    }
                    break;

                case 'notification':
                    scwin.addChatMessage("시스템", data.message, false);
                    break;

                case 'error':

                    scwin.addChatMessage("시스템", `⚠️ 서버 오류: ${data.message}`, false);
                    break;

                default:

                    break;
                }
    } catch (error) {

            }
        };

        chatSocket.onclose = function(event) {


            if (event.code !== 1000 && event.code !== 1001) { // 정상 종료가 아닐 때만 재연결
                const wasJoined = isJoined; // 화상통화 상태 백업

                if (!window.wsReconnectAttempts) {
                    window.wsReconnectAttempts = 0;
                }

                if (window.wsReconnectAttempts < 5) { // 최대 5번 재연결 시도
                    window.wsReconnectAttempts++;



                    setTimeout(() => {


                        // 재연결 시도
                        scwin.initializeChatWebSocket();

                        // 화상통화 중이었다면 상태 복원 준비
                        if (wasJoined) {
                            setTimeout(() => {
                                if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
                                    const joinRoomMessage = {
                                        type: 'join-room',
                                        channelName: currentUser.channelName,
                                        userId: currentUser.userId,
                                        userName: currentUser.userName,
                                        timestamp: Date.now()
                                    };
                                    chatSocket.send(JSON.stringify(joinRoomMessage));

                                }
                            }, 2000);
                        }

                    }, 3000 * window.wsReconnectAttempts); // 점진적으로 대기 시간 증가
                } else {

                }
            }
        };

        chatSocket.onerror = function(error) {


        };

    } catch (error) {

    }
};

// 채팅 메시지 추가 (timestamp 매개변수 추가)
scwin.addChatMessage = function(userName, message, isOwn, messageId, messageTimestamp) {
    if (!userName || !message) return;

    const msgId = messageId || `msg_${Date.now()}_${Math.random()}`;

    // 중복 메시지 방지
    if (window.addedMessageIds && window.addedMessageIds.has(msgId)) {
        return;
    }

    if (!window.addedMessageIds) {
        window.addedMessageIds = new Set();
    }
    window.addedMessageIds.add(msgId);

    // 실제 메시지 전송 시간 사용 (서버에서 받은 timestamp 또는 현재 시간)
    let displayTime;
    if (messageTimestamp) {
        // 서버에서 받은 timestamp 사용 (밀리초 단위)
        displayTime = new Date(messageTimestamp).toLocaleTimeString();
    } else {
        // 현재 시간 사용 (새 메시지인 경우)
        displayTime = new Date().toLocaleTimeString();
    }

    // 웹스퀘어 데이터리스트에 메시지 추가
    const rowIndex = dlt_chatMessages.insertRow();
    dlt_chatMessages.setCellData(rowIndex, "messageId", msgId);
    dlt_chatMessages.setCellData(rowIndex, "userId", isOwn ? currentUser.userId : (userName === "시스템" ? "system" : "other"));
    dlt_chatMessages.setCellData(rowIndex, "userName", userName);
    dlt_chatMessages.setCellData(rowIndex, "message", message);
    dlt_chatMessages.setCellData(rowIndex, "timestamp", displayTime);
    dlt_chatMessages.setCellData(rowIndex, "isOwn", isOwn ? "true" : "false");

    // 실제 화면에 메시지 표시
    const chatMessages = document.getElementById("chatMessages");
    if (chatMessages) {
        const messageDiv = document.createElement("div");
        messageDiv.className = `chat-message ${isOwn ? 'own' : 'other'}`;
        messageDiv.style.cssText = `
            margin: 8px 0;
            padding: 8px 12px;
            border-radius: 8px;
            max-width: 80%;
            word-wrap: break-word;
            ${isOwn ? 
                'background: #FFB823; color: white; margin-left: auto; text-align: right;' : 
                'background: #f1f3f5; color: #333; margin-right: auto; text-align: left;'
            }
        `;

        messageDiv.innerHTML = `
            <div style="font-weight: bold; font-size: 11px; margin-bottom: 4px; opacity: 0.8;">
                ${userName} ${displayTime}
            </div>
            <div style="font-size: 14px; line-height: 1.4;">
                ${message}
            </div>
        `;

        chatMessages.appendChild(messageDiv);

        // 채팅 화면을 최신 메시지로 스크롤
        setTimeout(() => {
            chatMessages.scrollTop = chatMessages.scrollHeight;
        }, 100);
    } else {

    }


};

// 채팅 메시지 전송
scwin.sendChatMessage = function() {
    const chatInput = document.getElementById("chatInput");
    if (!chatInput) return;

    const message = chatInput.value.trim();
    if (!message) return;

    if (!chatSocket || chatSocket.readyState !== WebSocket.OPEN) {
        $c.win.alert("서버에 연결되지 않았습니다.");
        return;
    }

    const messageId = `msg_${Date.now()}_${Math.random()}`;
    const messageData = {
        type: 'message',
        channelName: currentUser.channelName,
        userId: currentUser.userId,
        userName: currentUser.userName,
        message: message,
        messageId: messageId,
        timestamp: Date.now()
    };

    try {
        chatSocket.send(JSON.stringify(messageData));
        scwin.addChatMessage(currentUser.userName, message, true, messageId, messageData.timestamp);
        chatInput.value = "";

    } catch (error) {

        $c.win.alert("메시지 전송에 실패했습니다.");
    }
};

