// ===== Simple WebRTC 관련 함수들 =====

// 화상통화 나가기
/**
 * 화상통화 나가기 및 전체 정리
 * 모든 P2P 연결 종료, 로컬 스트림 정지, WebSocket 연결 종료, UI 상태 초기화
 * @returns {void}
 */
scwin.leaveCall = function() {
    try {
        // 모든 P2P 연결 종료
        peerConnections.forEach((pc, userId) => {
            pc.close();
        });
        peerConnections.clear();

        // 로컬 스트림 정지
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            localStream = null;
        }

        // 비디오 요소 초기화
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = null;
        }

        // 원격 비디오 제거
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.innerHTML = '';
        }

        // 나가기 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const leaveMessage = {
                type: 'leave-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(leaveMessage));
        }

        isJoined = false;
        dma_videoChat.set("isJoined", "false");

        // 내 비디오를 그리드에서 제거
        scwin.removeMyVideoFromGrid();

        scwin.updateControlButtons();




        // 프로젝트 설정과 동일한 방식으로 모달 닫기 (projectSettingSideMenu.xml의 btn_back_onclick 방식)
        try {


            // 방법 1: 부모의 closeVideoChatModal 함수 직접 호출
            if (window.parent && window.parent.scwin && window.parent.scwin.closeVideoChatModal) {

                window.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 2: 최상위 부모의 함수 호출  
            if (window.parent && window.parent.parent && window.parent.parent.scwin && window.parent.parent.scwin.closeVideoChatModal) {

                window.parent.parent.scwin.closeVideoChatModal();
                return; // 성공하면 여기서 끝
            }

            // 방법 3: 직접 부모에게 메시지 전송
            if (window.parent) {

                window.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 4: 최상위 부모에게 메시지 전송
            if (window.parent && window.parent.parent) {

                window.parent.parent.postMessage({action: 'closeVideoChatPopup'}, '*');
            }

            // 방법 5: 강제 닫기 시도

            setTimeout(function() {
                if (window.close) {

                    window.close();
                } else if (window.parent && window.parent.close) {

                    window.parent.close();
                } else {

                    window.history.back();
                }
            }, 100);

        } catch(closeError) {

            // 최후의 수단
            try {

                window.history.back();
            } catch(e2) {

            }
        }

    } catch (error) {

        // 오류 발생 시 모달 닫기 시도
        try {
            if (window.parent && window.parent.scwin && window.parent.scwin.closeVideoChatModal) {
                window.parent.scwin.closeVideoChatModal();
            } else {
                window.history.back();
            }
        } catch (backError) {
            window.location.href = '/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/ui/mainPage.xml';
        }
    }
};

// 음소거 토글
/**
 * 음소거 상태 토글
 * 로컬 오디오 트랙의 활성화/비활성화 상태를 전환하고 UI 업데이트
 * @returns {void}
 */
scwin.toggleMute = function() {
    if (localStream) {
        const audioTrack = localStream.getAudioTracks()[0];
        if (audioTrack) {
            audioTrack.enabled = !audioTrack.enabled;
            const muteBtn = document.getElementById("muteBtn");
            if (muteBtn) {
                muteBtn.textContent = audioTrack.enabled ? "MIC" : "음소거";
                muteBtn.classList.toggle("muted", !audioTrack.enabled);
            }

            // 그리드에 있는 내 비디오의 사용자 이름에 음소거 표시
            const myUserNameInGrid = document.querySelector('[data-username="나"] .remote-user-name');
            if (myUserNameInGrid) {
                if (audioTrack.enabled) {
                    myUserNameInGrid.style.background = '#FFB823';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName})`;
                } else {
                    myUserNameInGrid.style.background = '#dc3545';
                    myUserNameInGrid.textContent = `나 (${currentUser.userName}) - 음소거`;
                }
            }



        }
    }
};

// 비디오 토글
/**
 * 비디오 상태 토글
 * 로컬 비디오 트랙의 활성화/비활성화 상태를 전환하고 UI 업데이트
 * @returns {void}
 */
scwin.toggleVideo = function() {
    if (localStream) {
        const videoTrack = localStream.getVideoTracks()[0];
        if (videoTrack) {
            videoTrack.enabled = !videoTrack.enabled;
            const videoBtn = document.getElementById("videoBtn");
            if (videoBtn) {
                videoBtn.textContent = videoTrack.enabled ? "CAM" : "CAM OFF";
                videoBtn.classList.toggle("off", !videoTrack.enabled);
            }

            // 그리드에 있는 내 비디오에도 반영
            const myVideoContainer = document.querySelector('[data-username="나"] .remote-video-player');
            if (myVideoContainer) {
                const myVideoInGrid = myVideoContainer.querySelector('video');
                if (videoTrack.enabled) {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'block';
                    // 카메라 꺼짐 메시지 제거
                    const offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (offMessage) offMessage.remove();
                } else {
                    if (myVideoInGrid) myVideoInGrid.style.display = 'none';
                    // 카메라 꺼짐 메시지 표시
                    let offMessage = myVideoContainer.querySelector('.camera-off-message');
                    if (!offMessage) {
                        offMessage = document.createElement('div');
                        offMessage.className = 'camera-off-message';
                        offMessage.style.cssText = `
                            position: absolute;
                            top: 50%;
                            left: 50%;
                            transform: translate(-50%, -50%);
                            color: white;
                            font-size: 18px;
                            font-weight: bold;
                            text-align: center;
                            background: rgba(0,0,0,0.7);
                            padding: 10px;
                            border-radius: 8px;
                        `;
                        offMessage.textContent = '카메라 꺼짐';
                        myVideoContainer.appendChild(offMessage);
                    }
                }
            }


        }
    }
};

// 미니 PIP 모드 상태
let isMiniPipActive = false;

// PIP 상태 저장을 위한 전역 변수
let pipVideoState = null;

// 현재 화상통화 상태를 저장하는 함수
scwin.saveVideoStateToParent = function() {


    try {
        // 비디오 엘리먼트들 수집
        const localVideo = document.getElementById('localVideo');
        const remoteVideos = document.querySelectorAll('#remoteVideosGrid video');

        // 상태 정보 저장
        pipVideoState = {
            projectId: projectId,
            channelName: currentUser.channelName,
            userId: currentUser.userId,
            userName: currentUser.userName,
            isJoined: !!localVideo || remoteVideos.length > 0,
            localStream: localVideo ? localVideo.srcObject : null,
            remoteStreams: [],
            participants: []
        };

        // 원격 비디오 정보 저장
        remoteVideos.forEach((video, index) => {
            if (video.srcObject) {
                const container = video.closest('.remote-user-video');
                const nameElement = container ? container.querySelector('.remote-user-name') : null;
                pipVideoState.remoteStreams.push({
                    stream: video.srcObject,
                    userName: nameElement ? nameElement.textContent : `참가자 ${index + 1}`
                });
            }
        });

        // WebRTC 연결 상태 저장
        pipVideoState.webrtcState = {
            mediasoupSocket: mediasoupSocket,
            sendTransport: sendTransport,
            recvTransport: recvTransport,
            device: device,
            videoProducer: videoProducer,
            audioProducer: audioProducer,
            consumers: consumers
        };



        // 부모 페이지에 상태 전달
        if (window.parent) {
            window.parent.postMessage({
                action: 'saveVideoChatState',
                state: {
                    projectId: pipVideoState.projectId,
                    channelName: pipVideoState.channelName,
                    userId: pipVideoState.userId,
                    userName: pipVideoState.userName,
                    isJoined: pipVideoState.isJoined,
                    remoteStreamsCount: pipVideoState.remoteStreams.length
                }
            }, '*');
        }

    } catch (error) {

    }
};

// Picture-in-Picture 토글 상태 변수
let isPipMode = false;

// Picture-in-Picture 토글 (Method 1 - 별도 컨테이너 사용)
scwin.togglePiP = function() {


    // 로컬 비디오와 원격 비디오 확인
    const localVideo = document.getElementById('localVideo');
    const remoteVideos = document.querySelectorAll('#remoteVideosGrid video');

    if (!localVideo && remoteVideos.length === 0) {
        $c.win.alert('비디오를 찾을 수 없습니다. 먼저 화상통화에 참여해주세요.');
        return;
    }

    try {
        if (!isPipMode) {
            // PIP 모드로 전환


            // 1. 부모창에 모달 축소 요청
            if (window.parent && window.parent !== window) {
                try {


                    window.parent.postMessage({
                        action: 'resizeModalToPip',
                        source: 'videoChatPage',
                        timestamp: Date.now()
                    }, '*');


                    // 추가 확인을 위한 다중 전송
                    setTimeout(() => {
                        window.parent.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_retry',
                            timestamp: Date.now()
                        }, '*');

                    }, 100);

                } catch (e) {

                }
            } else {


                // 대체 방법 1: window.opener 사용
                if (window.opener && window.opener !== window) {
                    try {

                        window.opener.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_opener',
                            timestamp: Date.now()
                        }, '*');

                    } catch (openerError) {

                    }
                }

                // 대체 방법 2: window.top 사용
                else if (window.top && window.top !== window) {
                    try {

                        window.top.postMessage({
                            action: 'resizeModalToPip',
                            source: 'videoChatPage_top',
                            timestamp: Date.now()
                        }, '*');

                    } catch (topError) {

                    }
                }

                // 대체 방법 3: PostMessage 재시도 + 직접 DOM 조작 백업
                setTimeout(() => {


                    // 모든 가능한 부모 창에 PostMessage 전송
                    const targets = [
                        { win: window.parent, name: 'window.parent' },
                        { win: window.opener, name: 'window.opener' },
                        { win: window.top, name: 'window.top' }
                    ];

                    let messagesSent = 0;
                    targets.forEach(({ win, name }) => {
                        if (win && win !== window) {
                            try {
                                win.postMessage({
                                    action: 'resizeModalToPip',
                                    source: `videoChatPage_${name}_retry`,
                                    timestamp: Date.now(),
                                    retry: true
                                }, '*');
                                messagesSent++;

                            } catch (error) {

                            }
                        }
                    });

                    // PostMessage가 모두 실패했을 경우 직접 DOM 조작
                    if (messagesSent === 0) {
                        setTimeout(() => {

                            try {
                                let modalElement = null;

                                // 다양한 방법으로 모달 요소 찾기
                                const searchMethods = [
                                    () => document.querySelector('[id*="videoChatPopup"]'),
                                    () => window.parent?.document?.querySelector('[id*="videoChatPopup"]'),
                                    () => window.top?.document?.querySelector('[id*="videoChatPopup"]'),
                                    () => window.parent?.document?.querySelector('[id*="mf_wfr_mainContent_videoChatPopup"]'),
                                ];

                                for (const method of searchMethods) {
                                    try {
                                        modalElement = method();
                                        if (modalElement && modalElement.offsetWidth > 0) {

                                            break;
                                        }
                                    } catch (e) {
                                        // 접근 권한 오류 무시하고 다음 방법 시도
                                    }
                                }

                                if (modalElement) {
                                    // 직접 PIP 크기로 변경
                                    modalElement.style.setProperty('width', '320px', 'important');
                                    modalElement.style.setProperty('height', '240px', 'important');
                                    modalElement.style.setProperty('position', 'fixed', 'important');
                                    modalElement.style.setProperty('bottom', '20px', 'important');
                                    modalElement.style.setProperty('right', '20px', 'important');
                                    modalElement.style.setProperty('top', 'auto', 'important');
                                    modalElement.style.setProperty('left', 'auto', 'important');
                                    modalElement.style.setProperty('z-index', '999999', 'important');


                                } else {

                                }
                            } catch (domError) {

                            }
                        }, 200);
                    }
                }, 100);
            }

            // 2. 내부 UI를 PIP 모드로 변경
            scwin.applyPipModeUI();
            isPipMode = true;

            // PIP 버튼 텍스트 변경
            const pipBtn = document.getElementById('pipBtn');
            if (pipBtn) {
                const pipLabel = pipBtn.querySelector('xf\\:label, label');
                if (pipLabel) pipLabel.textContent = '확대';
                pipBtn.classList.add('active');
            }

        } else {
            // 일반 모드로 복원


            // 1. 부모창에 모달 복원 요청
            if (window.parent && window.parent !== window) {
                try {


                    window.parent.postMessage({
                        action: 'expandModalFromPip',
                        source: 'videoChatPage',
                        timestamp: Date.now()
                    }, '*');


                } catch (e) {

                }
            } else {

            }

            // 2. 내부 UI를 일반 모드로 복원
            scwin.restoreUIFromPip();
            isPipMode = false;

            // PIP 버튼 텍스트 변경
            const pipBtn = document.getElementById('pipBtn');
            if (pipBtn) {
                const pipLabel = pipBtn.querySelector('xf\\:label, label');
                if (pipLabel) pipLabel.textContent = 'PIP';
                pipBtn.classList.remove('active');
            }
        }

    } catch (error) {

        $c.win.alert('PIP 모드 전환에 실패했습니다: ' + error.message);
    }
};

// PIP 모드 UI 적용
scwin.applyPipModeUI = function() {

    setTimeout(() => {
        const mainContainer = document.querySelector('.video-chat-container');
        const chatSection = document.querySelector('.chat-section');
        const controlPanel = document.querySelector('.control-panel');
        const localVideoContainer = document.querySelector('.local-video-container');

        if (mainContainer) {
            // 메인 컨테이너를 PIP 레이아웃으로 변경
            mainContainer.style.setProperty('flex-direction', 'column', 'important');
            mainContainer.style.setProperty('height', '100%', 'important');

        }

        // 채팅 섹션 숨기기
        if (chatSection) {
            chatSection.style.setProperty('display', 'none', 'important');

        }

        // 컨트롤 패널 PIP용으로 축소
        if (controlPanel) {
            controlPanel.style.setProperty('bottom', '5px', 'important');
            controlPanel.style.setProperty('gap', '5px', 'important');

            // 컨트롤 버튼들 축소
            const controlBtns = controlPanel.querySelectorAll('.control-btn');
            controlBtns.forEach(btn => {
                btn.style.setProperty('width', '30px', 'important');
                btn.style.setProperty('height', '30px', 'important');
                btn.style.setProperty('font-size', '10px', 'important');
            });

        }

        // 로컬 비디오를 더 작게 조정
        if (localVideoContainer) {
            localVideoContainer.style.setProperty('width', '80px', 'important');
            localVideoContainer.style.setProperty('height', '60px', 'important');
            localVideoContainer.style.setProperty('top', '5px', 'important');
            localVideoContainer.style.setProperty('right', '5px', 'important');

        }

        // 원격 비디오 그리드 조정
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.style.setProperty('padding', '5px', 'important');
            remoteVideosGrid.style.setProperty('grid-gap', '3px', 'important');
            remoteVideosGrid.style.setProperty('grid-template-columns', '1fr', 'important');

        }

        // PIP 모드에서 확대 버튼 추가
        scwin.addPipExpandButton();

    }, 100);
};

// PIP 모드에서 확대 버튼 추가
scwin.addPipExpandButton = function() {


    // 기존 버튼이 있으면 제거
    const existingBtn = document.querySelector('.pip-expand-btn');
    if (existingBtn) {
        existingBtn.remove();

    }

    // 확대 버튼 생성
    const expandBtn = document.createElement('button');
    expandBtn.className = 'pip-expand-btn';
    expandBtn.innerHTML = '⛶'; // 확대 아이콘
    expandBtn.title = '전체화면으로 확대';

    // 클릭 이벤트 추가
    expandBtn.addEventListener('click', function(e) {
        e.preventDefault();
        e.stopPropagation();


        // 확대 로직 실행
        scwin.expandFromPipMode();
    });

    // 비디오 컨테이너에 추가
    const videoContainer = document.querySelector('.video-chat-container');
    if (videoContainer) {
        videoContainer.appendChild(expandBtn);

    } else {

    }
};

// PIP 모드에서 확대 로직
scwin.expandFromPipMode = function() {


    // 1. 부모창에 모달 복원 요청 (강화된 방식)
    try {
        // 방법 1: window.parent 사용
        if (window.parent && window.parent !== window) {
            try {

                window.parent.postMessage({
                    action: 'expandModalFromPip',
                    source: 'videoChatPage_expandBtn_parent',
                    timestamp: Date.now()
                }, '*');

            } catch (parentError) {

            }
        } else {

        }

        // 방법 2: window.opener 사용
        if (window.opener && window.opener !== window) {
            try {

                window.opener.postMessage({
                    action: 'expandModalFromPip',
                    source: 'videoChatPage_expandBtn_opener',
                    timestamp: Date.now()
                }, '*');

            } catch (openerError) {

            }
        }

        // 방법 3: window.top 사용
        if (window.top && window.top !== window) {
            try {

                window.top.postMessage({
                    action: 'expandModalFromPip',
                    source: 'videoChatPage_expandBtn_top',
                    timestamp: Date.now()
                }, '*');

            } catch (topError) {

            }
        }

        // 방법 4: 직접 DOM 조작 백업 (PostMessage 실패 시)
        setTimeout(() => {

            try {
                let modalElement = null;

                // 다양한 방법으로 모달 요소 찾기
                const searchMethods = [
                    () => document.querySelector('[id*="videoChatPopup"]'),
                    () => window.parent?.document?.querySelector('[id*="videoChatPopup"]'),
                    () => window.top?.document?.querySelector('[id*="videoChatPopup"]'),
                    () => window.parent?.document?.querySelector('[id*="mf_wfr_mainContent_videoChatPopup"]'),
                ];

                for (const method of searchMethods) {
                    try {
                        modalElement = method();
                        if (modalElement && modalElement.offsetWidth > 0) {

                            break;
                        }
                    } catch (e) {
                        // 접근 권한 오류 무시하고 다음 방법 시도
                    }
                }

                if (modalElement) {
                    // 직접 모달을 1920x940으로 확대
                    modalElement.style.setProperty('width', '1920px', 'important');
                    modalElement.style.setProperty('height', '940px', 'important');
                    modalElement.style.setProperty('position', 'absolute', 'important');
                    modalElement.style.setProperty('left', '0px', 'important');
                    modalElement.style.setProperty('top', '0px', 'important');
                    modalElement.style.setProperty('bottom', 'auto', 'important');
                    modalElement.style.setProperty('right', 'auto', 'important');
                    modalElement.style.setProperty('z-index', '999999', 'important');

                    // 확대 버튼 제거
                    const expandBtn = modalElement.querySelector('.pip-expand-btn');
                    if (expandBtn) expandBtn.remove();


                } else {

                }
            } catch (domError) {

            }
        }, 300);

    } catch (error) {

    }

    // 2. 내부 UI 복원
    scwin.restoreUIFromPip();
    isPipMode = false;

    // 3. PIP 버튼 텍스트 변경
    const pipBtn = document.getElementById('pipBtn');
    if (pipBtn) {
        const pipLabel = pipBtn.querySelector('xf\\:label, label');
        if (pipLabel) pipLabel.textContent = 'PIP';
        pipBtn.classList.remove('active');
    }


};

// PIP 에서 복원 메시지 처리
window.addEventListener('message', function(event) {
    if (event.data && event.data.action === 'restoreFromPip') {

        scwin.restoreUIFromPip();
        isPipMode = false;

        // PIP 버튼 텍스트 변경
        const pipBtn = document.getElementById('pipBtn');
        if (pipBtn) {
            const pipLabel = pipBtn.querySelector('xf\\:label, label');
            if (pipLabel) pipLabel.textContent = 'PIP';
            pipBtn.classList.remove('active');
        }
    }
});

// PIP에서 UI 복원
scwin.restoreUIFromPip = function() {


    try {
        const mainContainer = document.querySelector('.video-chat-container');
        const chatSection = document.querySelector('.chat-section');
        const controlPanel = document.querySelector('.control-panel');
        const localVideoContainer = document.querySelector('.local-video-container');

        // 메인 컨테이너 복원
        if (mainContainer) {
            mainContainer.style.removeProperty('flex-direction');
            mainContainer.style.removeProperty('height');

        }

        // 채팅 섹션 복원
        if (chatSection) {
            chatSection.style.removeProperty('display');

        }

        // 컨트롤 패널 복원
        if (controlPanel) {
            controlPanel.style.removeProperty('bottom');
            controlPanel.style.removeProperty('gap');

            // 컨트롤 버튼들 복원
            const controlBtns = controlPanel.querySelectorAll('.control-btn');
            controlBtns.forEach(btn => {
                btn.style.removeProperty('width');
                btn.style.removeProperty('height');
                btn.style.removeProperty('font-size');
            });

        }

        // 로컬 비디오 복원
        if (localVideoContainer) {
            localVideoContainer.style.removeProperty('width');
            localVideoContainer.style.removeProperty('height');
            localVideoContainer.style.removeProperty('top');
            localVideoContainer.style.removeProperty('right');

        }

        // 원격 비디오 그리드 복원
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (remoteVideosGrid) {
            remoteVideosGrid.style.removeProperty('padding');
            remoteVideosGrid.style.removeProperty('grid-gap');
            remoteVideosGrid.style.removeProperty('grid-template-columns');

        }

        // PIP 확대 버튼 제거
        const expandBtn = document.querySelector('.pip-expand-btn');
        if (expandBtn) {
            expandBtn.remove();

        }



    } catch (error) {

    }
};

// 비디오 상태를 부모 페이지에 저장하는 함수
scwin.saveVideoStateToParent = function() {
    try {


        // 현재 비디오 상태 수집
        const videoState = {
            localStream: localStream,
            peerConnections: peerConnections,
            currentUser: currentUser,
            isJoined: isJoined,
            isMuted: isMuted,
            isVideoOff: isVideoOff,
            remoteStreams: remoteStreams,
            remoteUserInfo: remoteUserInfo,
            chatSocket: chatSocket
        };

        // 부모 페이지에 비디오 상태 저장
        if (window.parent && window.parent.scwin) {
            window.parent.scwin.videoConnectionState = videoState;

        }

        // 로컬 스토리지에도 임시 저장 (백업용)
        try {
            const simpleState = {
                userId: currentUser.userId,
                userName: currentUser.userName,
                channelName: currentUser.channelName,
                isJoined: isJoined,
                isMuted: isMuted,
                isVideoOff: isVideoOff,
                participantCount: peerConnections.size
            };
            localStorage.setItem('tempVideoChatState', JSON.stringify(simpleState));
        } catch (e) {

        }

    } catch (error) {

    }
};

// PIP 새창 열기
scwin.openPipWindow = function() {


    // 새창 옵션 설정 (작고 오른쪽 하단에 위치)
    const screenWidth = window.screen.availWidth;
    const screenHeight = window.screen.availHeight;
    const pipWidth = 400;
    const pipHeight = 300;
    const pipLeft = screenWidth - pipWidth - 20; // 오른쪽에서 20px 떨어짐
    const pipTop = screenHeight - pipHeight - 60; // 아래에서 60px 떨어짐 (작업표시줄 고려)

    const windowFeatures = [
        `width=${pipWidth}`,
        `height=${pipHeight}`,
        `left=${pipLeft}`,
        `top=${pipTop}`,
        'resizable=yes',
        'scrollbars=yes',
        'toolbar=no',
        'menubar=no',
        'location=no',
        'directories=no',
        'status=no'
    ].join(',');

    // 현재 화상통화 페이지 URL 가져오기
    const currentUrl = window.location.href;

    // PIP 모드 파라미터 추가
    const pipUrl = currentUrl + (currentUrl.includes('?') ? '&' : '?') + 'pipMode=true';



    // 새창 열기
    const pipWindow = window.open(pipUrl, 'pipVideoChat', windowFeatures);

    if (!pipWindow) {
        throw new Error('팝업이 차단되었습니다. 브라우저 팝업 차단을 해제해주세요.');
    }

    // 새창 포커스
    pipWindow.focus();


    return pipWindow;
};

// PIP 종료 이벤트 리스너 등록
scwin.setupPipEventListeners = function() {
    // PIP 종료 이벤트 감지
    document.addEventListener('leavepictureinpicture', function(event) {

        // 필요시 화상통화 페이지로 돌아가는 로직 추가
    });

    // PIP 시작 이벤트 감지
    document.addEventListener('enterpictureinpicture', function(event) {

        // PIP 버튼 상태 업데이트
        const pipBtn = document.getElementById('pipBtn');
        if (pipBtn) {
            pipBtn.classList.add('active');
        }
    });


};

// 미니 PIP 표시 (원래 방식: 별도 PIP 컨테이너)
scwin.showMiniPIP = function() {


    const miniPipContainer = document.getElementById('miniPipContainer');
    const mainContainer = document.querySelector('.video-chat-container');

    if (!miniPipContainer || !mainContainer) {

        return;
    }

    // 1. 메인 화상통화 영역 숨기기
    mainContainer.style.display = 'none';


    // 2. 미니 PIP 컨테이너 표시 (강제로 보이게 설정)
    miniPipContainer.style.setProperty('display', 'block', 'important');
    miniPipContainer.style.setProperty('visibility', 'visible', 'important');
    miniPipContainer.style.setProperty('opacity', '1', 'important');

    // 3. 위치 강제 설정
    miniPipContainer.style.setProperty('position', 'fixed', 'important');
    miniPipContainer.style.setProperty('bottom', '20px', 'important');
    miniPipContainer.style.setProperty('right', '20px', 'important');
    miniPipContainer.style.setProperty('z-index', '9999', 'important');

    // 4. PIP 크기에 맞춰 비디오 그리드 레이아웃 적용
    scwin.updateVideoGridLayout(miniPipContainer);



    // 5. 비디오들을 미니 PIP에 복사
    scwin.updateMiniPIP();

    // 6. PIP 상태 설정
    isMiniPipActive = true;
    scwin.updatePiPButton(true);


};

// PIP 모드용 비디오 조정 함수
scwin.adjustVideosForPIP = function() {


    // 모든 비디오 요소 검색 (더 넓은 범위)
    const allVideos = document.querySelectorAll('video');


    allVideos.forEach(function(video, index) {
        video.style.setProperty('width', '150px', 'important');
        video.style.setProperty('height', '100px', 'important');
        video.style.setProperty('object-fit', 'cover', 'important');
        video.style.setProperty('border-radius', '6px', 'important');
        video.style.setProperty('background', 'red', 'important'); // 디버깅용
    });

    // 로컬 비디오 조정
    const localVideo = document.getElementById('localVideo');
    const localContainer = document.querySelector('.local-video-container');

    if (localVideo) {
        localVideo.style.setProperty('width', '180px', 'important');
        localVideo.style.setProperty('height', '120px', 'important');
        localVideo.style.setProperty('object-fit', 'cover', 'important');
        localVideo.style.setProperty('border-radius', '6px', 'important');
        localVideo.style.setProperty('background', 'blue', 'important'); // 디버깅용

    } else {

    }

    if (localContainer) {
        localContainer.style.setProperty('width', '100%', 'important');
        localContainer.style.setProperty('height', '140px', 'important');
        localContainer.style.setProperty('margin', '2px', 'important');
        localContainer.style.setProperty('background', 'yellow', 'important'); // 디버깅용

    } else {

    }

    // 원격 비디오들 조정
    const remoteVideosGrid = document.getElementById('remoteVideosGrid');
    if (remoteVideosGrid) {
        remoteVideosGrid.style.setProperty('height', '140px', 'important');
        remoteVideosGrid.style.setProperty('grid-template-columns', '1fr 1fr', 'important');
        remoteVideosGrid.style.setProperty('grid-gap', '4px', 'important');
        remoteVideosGrid.style.setProperty('padding', '2px', 'important');
        remoteVideosGrid.style.setProperty('background', 'green', 'important'); // 디버깅용

    } else {

    }

    // 모든 원격 비디오 요소들 조정
    const remoteVideos = document.querySelectorAll('.remote-video');


    remoteVideos.forEach(function(video, index) {

        video.style.setProperty('width', '100%', 'important');
        video.style.setProperty('height', '100%', 'important');
        video.style.setProperty('object-fit', 'cover', 'important');
        video.style.setProperty('border-radius', '4px', 'important');
        video.style.setProperty('background', 'purple', 'important'); // 디버깅용
    });

    const remoteContainers = document.querySelectorAll('.remote-video-container');


    remoteContainers.forEach(function(container, index) {

        container.style.setProperty('width', '100%', 'important');
        container.style.setProperty('height', '65px', 'important');
        container.style.setProperty('margin', '1px', 'important');
        container.style.setProperty('background', 'orange', 'important'); // 디버깅용
    });


};

// PIP 모드에서 일반 모드로 비디오 복원
scwin.restoreVideosFromPIP = function() {


    // 로컬 비디오 복원
    const localVideo = document.getElementById('localVideo');
    const localContainer = document.querySelector('.local-video-container');

    if (localVideo) {
        localVideo.style.removeProperty('width');
        localVideo.style.removeProperty('height');
        localVideo.style.removeProperty('object-fit');
        localVideo.style.removeProperty('border-radius');
    }

    if (localContainer) {
        localContainer.style.removeProperty('width');
        localContainer.style.removeProperty('height');
        localContainer.style.removeProperty('margin');
    }

    // 원격 비디오들 복원
    const remoteVideosGrid = document.getElementById('remoteVideosGrid');
    if (remoteVideosGrid) {
        remoteVideosGrid.style.removeProperty('height');
        remoteVideosGrid.style.removeProperty('grid-template-columns');
        remoteVideosGrid.style.removeProperty('grid-gap');
        remoteVideosGrid.style.removeProperty('padding');
    }

    const remoteVideos = document.querySelectorAll('.remote-video');
    remoteVideos.forEach(function(video) {
        video.style.removeProperty('width');
        video.style.removeProperty('height');
        video.style.removeProperty('object-fit');
        video.style.removeProperty('border-radius');
    });

    const remoteContainers = document.querySelectorAll('.remote-video-container');
    remoteContainers.forEach(function(container) {
        container.style.removeProperty('width');
        container.style.removeProperty('height');
        container.style.removeProperty('margin');
    });



    // === 아래는 기존 코드 (위에서 return으로 실행되지 않음) ===
    // 전체 화상통화 영역 숨기기 (비디오 + 채팅)
    mainContainer.style.display = 'none';

    // 미니 PIP 컨테이너 표시 (강제로 보이게 설정)
    miniPipContainer.style.setProperty('display', 'block', 'important');
    miniPipContainer.style.setProperty('visibility', 'visible', 'important');
    miniPipContainer.style.setProperty('opacity', '1', 'important');

    // 위치도 강제로 설정
    miniPipContainer.style.setProperty('position', 'fixed', 'important');
    miniPipContainer.style.setProperty('bottom', '20px', 'important');
    miniPipContainer.style.setProperty('right', '20px', 'important');
    miniPipContainer.style.setProperty('z-index', '9999', 'important');

    // PIP 초기 표시 시 비디오 그리드 레이아웃 적용
    scwin.updateVideoGridLayout(miniPipContainer);



    // X 버튼 이벤트 리스너 강제 추가 (표시할 때마다)
    const closeBtn = document.getElementById('miniPipCloseBtn');
    if (closeBtn) {
        // 기존 모든 이벤트 제거
        closeBtn.onclick = null;
        closeBtn.removeAttribute('onclick');

        // 새로운 X 버튼으로 교체 (완전히 새로운 요소 생성)
        const newCloseBtn = closeBtn.cloneNode(true);
        closeBtn.parentNode.replaceChild(newCloseBtn, closeBtn);

        // 새 버튼에 이벤트 추가
        newCloseBtn.addEventListener('click', function(e) {

            e.preventDefault();
            e.stopPropagation();

            // PIP 닫기 기능
            const miniPipContainer = document.getElementById('miniPipContainer');
            const mainContainer = document.querySelector('.video-chat-container');

            if (miniPipContainer) {
                miniPipContainer.style.setProperty('display', 'none', 'important');


                // 추가: PIP 컨테이너 완전 제거 확인

            }
            if (mainContainer) {
                mainContainer.style.setProperty('display', 'flex', 'important');

            } else {
                // 메인 컨테이너가 없으면 부모창에 모달 재열기 요청

                if (window.parent && window.parent !== window) {
                    try {
                        window.parent.postMessage({
                            action: 'reopenVideoChatPopup'
                        }, '*');

                    } catch (e) {

                    }
                }
            }

            // 상태 업데이트
            isMiniPipActive = false;
            const pipBtn = document.getElementById("pipBtn");
            if (pipBtn) {
                pipBtn.classList.remove("active");
                pipBtn.textContent = "PIP";

            }


        }, true);


    } else {

    }

    // 모든 비디오를 미니 PIP에 복제
    scwin.updateMiniPIP();

    // 드래그 및 리사이즈 기능 즉시 초기화
    setTimeout(() => {


        // 인라인 드래그 기능 구현
        const pipContainer = document.querySelector('.mini-pip-container');
        const pipHeader = document.querySelector('.mini-pip-header');

        if (!pipContainer || !pipHeader) {

            return;
        }

        // 드래그 변수들
        let isDragging = false;
        let dragOffset = { x: 0, y: 0 };

        // 기존 이벤트 제거 후 새로 추가
        const newHeader = pipHeader.cloneNode(true);
        pipHeader.parentNode.replaceChild(newHeader, pipHeader);

        newHeader.style.cursor = 'move';
        newHeader.addEventListener('mousedown', function(e) {
            if (e.target.closest('.mini-pip-close')) return;


            isDragging = true;

            const rect = pipContainer.getBoundingClientRect();
            dragOffset.x = e.clientX - rect.left;
            dragOffset.y = e.clientY - rect.top;

            function dragMove(e) {
                if (!isDragging) return;

                const newX = e.clientX - dragOffset.x;
                const newY = e.clientY - dragOffset.y;

                const maxX = window.innerWidth - pipContainer.offsetWidth;
                const maxY = window.innerHeight - pipContainer.offsetHeight;

                const x = Math.max(0, Math.min(newX, maxX));
                const y = Math.max(0, Math.min(newY, maxY));

                pipContainer.style.setProperty('left', x + 'px', 'important');
                pipContainer.style.setProperty('top', y + 'px', 'important');
                pipContainer.style.setProperty('right', 'auto', 'important');
                pipContainer.style.setProperty('bottom', 'auto', 'important');
            }

            function dragEnd() {

                isDragging = false;
                document.removeEventListener('mousemove', dragMove);
                document.removeEventListener('mouseup', dragEnd);
            }

            document.addEventListener('mousemove', dragMove);
            document.addEventListener('mouseup', dragEnd);
            e.preventDefault();
        });

        // 리사이즈 핸들 생성 및 기능 추가
        const handles = [
            { class: 'corner se', cursor: 'se-resize', style: 'bottom: 0; right: 0; width: 15px; height: 15px; border-radius: 0 0 12px 0;' },
            { class: 'corner sw', cursor: 'sw-resize', style: 'bottom: 0; left: 0; width: 15px; height: 15px; border-radius: 0 0 0 12px;' },
            { class: 'corner ne', cursor: 'ne-resize', style: 'top: 0; right: 0; width: 15px; height: 15px; border-radius: 0 12px 0 0;' },
            { class: 'corner nw', cursor: 'nw-resize', style: 'top: 0; left: 0; width: 15px; height: 15px; border-radius: 12px 0 0 0;' },
            { class: 'edge right', cursor: 'e-resize', style: 'right: 0; top: 15px; bottom: 15px; width: 5px;' },
            { class: 'edge left', cursor: 'w-resize', style: 'left: 0; top: 15px; bottom: 15px; width: 5px;' },
            { class: 'edge top', cursor: 'n-resize', style: 'top: 0; left: 15px; right: 15px; height: 5px;' },
            { class: 'edge bottom', cursor: 's-resize', style: 'bottom: 0; left: 15px; right: 15px; height: 5px;' }
        ];

        // 기존 핸들 제거
        pipContainer.querySelectorAll('.resize-handle').forEach(handle => handle.remove());

        handles.forEach(handleInfo => {
            const handle = document.createElement('div');
            handle.className = `resize-handle ${handleInfo.class}`;
            handle.style.cssText = `
                position: absolute;
                background: #FFB823;
                opacity: 0.5;
                z-index: 10002;
                cursor: ${handleInfo.cursor};
                ${handleInfo.style}
            `;

            let isResizing = false;
            let resizeStart = {};

            handle.addEventListener('mousedown', function(e) {

                isResizing = true;

                const rect = pipContainer.getBoundingClientRect();
                resizeStart = {
                    x: e.clientX,
                    y: e.clientY,
                    width: rect.width,
                    height: rect.height,
                    left: rect.left,
                    top: rect.top,
                    direction: handleInfo.class
                };

                function handleResize(e) {
                    if (!isResizing) return;

                    const deltaX = e.clientX - resizeStart.x;
                    const deltaY = e.clientY - resizeStart.y;
                    const direction = resizeStart.direction;

                    let newWidth = resizeStart.width;
                    let newHeight = resizeStart.height;
                    let newLeft = resizeStart.left;
                    let newTop = resizeStart.top;

                    // 방향에 따른 리사이즈 처리
                    if (direction.includes('right') || direction.includes('se') || direction.includes('ne')) {
                        newWidth = resizeStart.width + deltaX;
                    }
                    if (direction.includes('left') || direction.includes('sw') || direction.includes('nw')) {
                        newWidth = resizeStart.width - deltaX;
                        newLeft = resizeStart.left + deltaX;
                    }
                    if (direction.includes('bottom') || direction.includes('se') || direction.includes('sw')) {
                        newHeight = resizeStart.height + deltaY;
                    }
                    if (direction.includes('top') || direction.includes('ne') || direction.includes('nw')) {
                        newHeight = resizeStart.height - deltaY;
                        newTop = resizeStart.top + deltaY;
                    }

                    // 크기 제한
                    const minWidth = 250, maxWidth = Math.min(600, window.innerWidth * 0.8);
                    const minHeight = 200, maxHeight = window.innerHeight * 0.8;

                    if (newWidth < minWidth) {
                        if (direction.includes('left')) newLeft = resizeStart.left + (resizeStart.width - minWidth);
                        newWidth = minWidth;
                    }
                    if (newWidth > maxWidth) {
                        if (direction.includes('left')) newLeft = resizeStart.left + (resizeStart.width - maxWidth);
                        newWidth = maxWidth;
                    }
                    if (newHeight < minHeight) {
                        if (direction.includes('top')) newTop = resizeStart.top + (resizeStart.height - minHeight);
                        newHeight = minHeight;
                    }
                    if (newHeight > maxHeight) {
                        if (direction.includes('top')) newTop = resizeStart.top + (resizeStart.height - maxHeight);
                        newHeight = maxHeight;
                    }

                    // 화면 경계 체크
                    newLeft = Math.max(0, Math.min(newLeft, window.innerWidth - newWidth));
                    newTop = Math.max(0, Math.min(newTop, window.innerHeight - newHeight));

                    pipContainer.style.setProperty('width', newWidth + 'px', 'important');
                    pipContainer.style.setProperty('height', newHeight + 'px', 'important');
                    pipContainer.style.setProperty('left', newLeft + 'px', 'important');
                    pipContainer.style.setProperty('top', newTop + 'px', 'important');
                    pipContainer.style.setProperty('right', 'auto', 'important');
                    pipContainer.style.setProperty('bottom', 'auto', 'important');

                    // PIP 크기 변화에 따른 비디오 그리드 레이아웃 업데이트
                    scwin.updateVideoGridLayout(pipContainer);
                }

                function handleResizeEnd() {

                    isResizing = false;
                    document.removeEventListener('mousemove', handleResize);
                    document.removeEventListener('mouseup', handleResizeEnd);
                }

                document.addEventListener('mousemove', handleResize);
                document.addEventListener('mouseup', handleResizeEnd);
                e.preventDefault();
                e.stopPropagation();
            });

            handle.addEventListener('mouseenter', function() {
                handle.style.opacity = '1';
            });

            handle.addEventListener('mouseleave', function() {
                handle.style.opacity = '0.5';
            });

            pipContainer.appendChild(handle);
        });

        // X 버튼 이벤트 재바인딩 (리사이즈 핸들 추가 후)
        const finalCloseBtn = document.getElementById('miniPipCloseBtn');
        if (finalCloseBtn) {
            // 기존 이벤트 완전 제거
            finalCloseBtn.onclick = null;
            finalCloseBtn.removeAttribute('onclick');

            // 새로운 이벤트 추가 (최종)
            finalCloseBtn.addEventListener('click', function(e) {

                e.preventDefault();
                e.stopPropagation();

                // PIP 닫기
                const miniPip = document.getElementById('miniPipContainer');
                const mainCont = document.querySelector('.video-chat-container');

                if (miniPip) {
                    miniPip.style.setProperty('display', 'none', 'important');

                }

                if (mainCont) {
                    mainCont.style.setProperty('display', 'flex', 'important');
                    mainCont.style.setProperty('visibility', 'visible', 'important');

                } else {
                    // 모든 video-chat-container 강제 표시
                    document.querySelectorAll('.video-chat-container').forEach(cont => {
                        cont.style.setProperty('display', 'flex', 'important');
                        cont.style.setProperty('visibility', 'visible', 'important');
                    });

                }

                // 상태 업데이트
                isMiniPipActive = false;
                const pipButton = document.getElementById("pipBtn");
                if (pipButton) {
                    pipButton.classList.remove("active");
                    pipButton.textContent = "PIP";
                }


            }, { capture: true, once: false });

            // X 버튼 스타일 강화 (다른 요소에 가려지지 않도록)
            finalCloseBtn.style.setProperty('z-index', '10005', 'important');
            finalCloseBtn.style.setProperty('position', 'relative', 'important');
            finalCloseBtn.style.setProperty('pointer-events', 'auto', 'important');


        } else {

        }


    }, 100);

    // 상태 업데이트
    isMiniPipActive = true;
    scwin.updatePiPButton(true);


};

// 미니 PIP 닫기
scwin.closeMiniPIP = function() {


    const miniPipContainer = document.getElementById('miniPipContainer');
    const mainContainer = document.querySelector('.video-chat-container');



    if (!miniPipContainer || !mainContainer) {

        return;
    }

    // 미니 PIP 컨테이너 숨기기
    miniPipContainer.style.display = 'none';


    // 전체 화상통화 영역 표시 (비디오 + 채팅)
    mainContainer.style.display = 'flex';


    // 미니 비디오 그리드 비우기
    const miniVideoGrid = document.getElementById('miniVideoGrid');
    if (miniVideoGrid) {
        miniVideoGrid.innerHTML = '';

    }

    // 상태 업데이트
    isMiniPipActive = false;
    scwin.updatePiPButton(false);

    // 다른 팝업들의 헤더 복원
    scwin.restoreOtherPopupHeaders();


};

// PIP 확장 기능 (PIP 모드에서 전체 화면으로 복원)
scwin.expandVideoChat = function() {


    const mainContainer = document.querySelector('.video-chat-container');
    const chatSection = document.querySelector('.chat-section');
    const controlPanel = document.querySelector('.control-panel');
    const videoSection = document.querySelector('.video-section');

    if (!mainContainer || !videoSection) {

        return;
    }

    // PIP가 활성 상태인지 확인
    if (!isMiniPipActive) {

        return;
    }

    // 1. 메인 컨테이너 스타일 복원 (모든 PIP 스타일 제거)
    mainContainer.style.removeProperty('position');
    mainContainer.style.removeProperty('bottom');
    mainContainer.style.removeProperty('right');
    mainContainer.style.removeProperty('width');
    mainContainer.style.removeProperty('height');
    mainContainer.style.removeProperty('z-index');
    mainContainer.style.removeProperty('border-radius');
    mainContainer.style.removeProperty('border');
    mainContainer.style.removeProperty('box-shadow');
    mainContainer.style.removeProperty('background');


    // 2. 비디오 섹션 스타일 복원
    videoSection.style.removeProperty('width');
    videoSection.style.removeProperty('height');
    videoSection.style.removeProperty('padding');


    // 3. 채팅 영역 다시 표시
    if (chatSection) {
        chatSection.style.display = '';

    }

    // 4. 컨트롤 패널 다시 표시
    if (controlPanel) {
        controlPanel.style.display = '';

    }

    // 5. PIP 컨트롤 버튼들 숨기기
    const pipControls = document.getElementById('pipControls');
    if (pipControls) {
        pipControls.style.display = 'none';

    }

    // 6. PIP 모드 CSS 클래스 제거
    mainContainer.classList.remove('pip-mode');

    // 7. 비디오 요소들 복원
    scwin.restoreVideosFromPIP();

    // 8. 상태 업데이트
    isMiniPipActive = false;
    scwin.updatePiPButton(false);

    // 9. 드래그 기능 비활성화
    scwin.disablePipDrag(mainContainer);


};

// PIP 드래그 기능 활성화
scwin.enablePipDrag = function(container) {

    container.style.cursor = 'move';
    container.setAttribute('data-pip-draggable', 'true');

    // 기존 드래그 이벤트가 있다면 재사용
    if (typeof scwin.initializePipDrag === 'function') {
        scwin.initializePipDrag();
    }
};

// PIP 드래그 기능 비활성화
scwin.disablePipDrag = function(container) {

    container.style.cursor = '';
    container.removeAttribute('data-pip-draggable');
};

// PIP 버튼 상태 업데이트
scwin.updatePiPButton = function(isInPiP) {
    const pipBtn = document.getElementById('pipBtn');
    if (pipBtn) {
        const label = pipBtn.querySelector('xf\\:label');
        if (label) {
            label.textContent = isInPiP ? 'EXIT PIP' : 'PIP';
        }
        pipBtn.className = isInPiP ? 'control-btn pip-btn active' : 'control-btn pip-btn';
    }
};

// 미니 PIP 업데이트 (모든 비디오 복제)
scwin.updateMiniPIP = function() {


    const miniVideoGrid = document.getElementById('miniVideoGrid');
    if (!miniVideoGrid) {

        return;
    }

    // 기존 미니 비디오들 제거
    miniVideoGrid.innerHTML = '';


    // 로컬 비디오 추가
    const localVideo = document.getElementById('localVideo');
    if (localVideo && localVideo.srcObject) {

        const userName = (typeof currentUser !== 'undefined' && currentUser.userName) ? 
                        '나 (' + currentUser.userName + ')' : '나';
        scwin.addVideoToMiniPIP('local', localVideo.srcObject, userName);
    } else {

    }

    // 원격 비디오들 추가
    const remoteVideosGrid = document.getElementById('remoteVideosGrid');
    if (remoteVideosGrid) {
        const remoteVideoItems = remoteVideosGrid.querySelectorAll('.remote-video-item');


        remoteVideoItems.forEach((item, index) => {
            const video = item.querySelector('video');
            const userName = item.getAttribute('data-username') || item.getAttribute('data-userid') || '참가자' + (index + 1);
            const userId = item.getAttribute('data-userid') || item.getAttribute('data-username') || 'unknown_' + index;



            if (video && video.srcObject) {
                scwin.addVideoToMiniPIP(userId, video.srcObject, userName);
            }
        });
    } else {

    }

    // 불필요한 더미 비디오 생성 제거 (비디오 1,2,3,4,5 문제 해결)

    // PIP 크기에 맞춰 비디오 그리드 레이아웃 적용
    const pipContainer = document.getElementById('miniPipContainer');
    if (pipContainer) {
        scwin.updateVideoGridLayout(pipContainer);
    }


};

// PIP 크기에 따른 비디오 그리드 레이아웃 동적 업데이트
scwin.updateVideoGridLayout = function(pipContainer) {
    const miniVideoGrid = document.getElementById('miniVideoGrid');
    if (!miniVideoGrid || !pipContainer) return;

    const containerWidth = pipContainer.offsetWidth;
    const threshold = 280; // 280px 이하일 때 1열로 전환



    if (containerWidth < threshold) {
        // 1열 레이아웃으로 전환
        miniVideoGrid.style.gridTemplateColumns = '1fr';

    } else {
        // 2열 레이아웃 유지
        miniVideoGrid.style.gridTemplateColumns = 'repeat(2, 1fr)';

    }
};

// 개별 비디오를 미니 PIP에 추가
scwin.addVideoToMiniPIP = function(userId, stream, userName) {
    const miniVideoGrid = document.getElementById('miniVideoGrid');
    if (!miniVideoGrid || !stream) return;

    // 미니 비디오 아이템 생성
    const miniVideoItem = document.createElement('div');
    miniVideoItem.className = 'mini-video-item';
    miniVideoItem.setAttribute('data-userid', userId);

    // 비디오 요소 생성
    const miniVideo = document.createElement('video');
    miniVideo.className = 'mini-video';
    miniVideo.srcObject = stream;
    miniVideo.autoplay = true;
    miniVideo.playsInline = true;
    miniVideo.muted = (userId === 'local'); // 로컬 비디오만 음소거

    // 사용자 이름 라벨 생성
    const miniVideoName = document.createElement('div');
    miniVideoName.className = 'mini-video-name';
    miniVideoName.textContent = userName;

    // 비디오 꺼짐 메시지 (필요시 표시)
    const videoTracks = stream.getVideoTracks();
    if (videoTracks.length === 0 || !videoTracks[0].enabled) {
        miniVideo.style.display = 'none';
        const offMessage = document.createElement('div');
        offMessage.className = 'mini-video-off-message';
        offMessage.textContent = '카메라 꺼짐';
        miniVideoItem.appendChild(offMessage);
        miniVideoItem.classList.add('video-off');
    }

    // 음소거 상태 확인
    const audioTracks = stream.getAudioTracks();
    if (audioTracks.length === 0 || !audioTracks[0].enabled) {
        miniVideoItem.classList.add('muted');
        miniVideoName.style.background = '#dc3545';
    }

    // 요소들 조립
    miniVideoItem.appendChild(miniVideo);
    miniVideoItem.appendChild(miniVideoName);

    // 그리드에 추가
    miniVideoGrid.appendChild(miniVideoItem);


};

// 버튼 상태 업데이트
scwin.updateControlButtons = function() {
    const joinBtn = document.getElementById("joinBtn");
    const leaveBtn = document.getElementById("leaveBtn");
    const muteBtn = document.getElementById("muteBtn");
    const videoBtn = document.getElementById("videoBtn");
    const pipBtn = document.getElementById("pipBtn");

    if (isJoined) {
        if (joinBtn) joinBtn.style.display = "none";
        if (leaveBtn) leaveBtn.style.display = "inline-block";
        if (muteBtn) muteBtn.disabled = false;
        if (videoBtn) videoBtn.disabled = false;
        if (pipBtn) pipBtn.disabled = false;
    } else {
        if (joinBtn) joinBtn.style.display = "inline-block";
        if (leaveBtn) leaveBtn.style.display = "none";
        if (muteBtn) muteBtn.disabled = true;
        if (videoBtn) videoBtn.disabled = true;
        if (pipBtn) pipBtn.disabled = true;
    }
};

// 내 비디오를 그리드에 추가 (다른 참가자들과 동일한 레이아웃)
/**
 * 내 비디오를 그리드에 추가
 * 로컬 사용자의 비디오 스트림을 화상통화 그리드에 표시
 * @param {MediaStream} stream - 로컬 사용자의 비디오/오디오 스트림
 * @returns {void}
 */
scwin.addMyVideoToGrid = function(stream) {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) {

            return;
        }

        // 기존에 내 비디오가 있는지 확인
        const existingMyVideo = remoteVideosGrid.querySelector('[data-username="나"]');
        if (existingMyVideo) {
            existingMyVideo.remove();
        }

        // 내 비디오 아이템 생성
        const videoItem = document.createElement('div');
        videoItem.className = 'remote-user-video';
        videoItem.setAttribute('data-username', '나');
        videoItem.setAttribute('data-userid', currentUser.userId);

        videoItem.innerHTML = `
            <div class="remote-video-wrapper">
                <div class="remote-video-player">
                    <video autoplay muted playsinline style="
                        width: 100%; 
                        height: 100%; 
                        object-fit: cover; 
                        border-radius: 8px;
                        border: 3px solid #FFB823;
                    "></video>
                </div>
                <div class="remote-user-name" style="
                    background: #FFB823;
                    color: white;
                    font-weight: bold;
                ">나 (${currentUser.userName})</div>
            </div>
        `;

        // 비디오 스트림 연결
        const video = videoItem.querySelector('video');
        if (video && stream) {
            video.srcObject = stream;
        }

        // 그리드의 첫 번째 위치에 추가 (내가 맨 앞에 표시)
        remoteVideosGrid.insertBefore(videoItem, remoteVideosGrid.firstChild);




        // 미니 PIP가 활성화된 상태라면 업데이트
        if (isMiniPipActive) {
            scwin.updateMiniPIP();

        }

    } catch (error) {

    }
};

// 내 비디오를 그리드에서 제거
scwin.removeMyVideoFromGrid = function() {
    try {
        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) return;

        const myVideoItem = remoteVideosGrid.querySelector('[data-username="나"]');
        if (myVideoItem) {
            myVideoItem.remove();


            // 미니 PIP가 활성화된 상태라면 업데이트
            if (isMiniPipActive) {
                scwin.updateMiniPIP();

            }
        }
    } catch (error) {

    }
};

// 원격 사용자 제거 (개선된 버전)
scwin.removeRemoteUser = function(userId) {
    try {


        const remoteVideosGrid = document.getElementById('remoteVideosGrid');
        if (!remoteVideosGrid) {

            return;
        }

        // userId로 사용자 이름 찾기
        const userInfo = remoteUserInfo.get(userId);
        const userName = userInfo ? userInfo.userName : userId;

        // 여러 방법으로 비디오 아이템 찾기 시도
        let videoItem = null;

        // 방법 1: data-userid로 찾기
        videoItem = remoteVideosGrid.querySelector(`[data-userid="${userId}"]`);
        if (videoItem) {

        }

        // 방법 2: data-username으로 찾기
        if (!videoItem) {
            videoItem = remoteVideosGrid.querySelector(`[data-username="${userName}"]`);
            if (videoItem) {

            }
        }

        // 방법 3: 모든 원격 비디오에서 검색
        if (!videoItem) {
            const allVideoItems = remoteVideosGrid.querySelectorAll('.remote-video-item');


            allVideoItems.forEach((item, index) => {
                const itemUserId = item.getAttribute('data-userid');
                const itemUserName = item.getAttribute('data-username');


                if (itemUserId === userId || itemUserName === userName) {
                    videoItem = item;

                }
            });
        }

        // 비디오 제거 실행
        if (videoItem) {
            videoItem.remove();



            // 미니 PIP가 활성화된 상태라면 업데이트
            if (isMiniPipActive) {
                scwin.updateMiniPIP();

            }
        } else {

        }

        // 관련 데이터 정리
        if (remoteStreams.has(userId)) {
            remoteStreams.delete(userId);

        }

        if (pendingIceCandidates.has(userId)) {
            pendingIceCandidates.delete(userId);

        }



    } catch (error) {

    }
};

// 새 창에서 PIP 모드 열기
scwin.openPipInNewWindow = function() {
    try {
        // 현재 비디오 참가자들의 정보 수집
        const videoElements = document.querySelectorAll('.remote-user-video video');
        const participantCount = videoElements.length;

        // 새 창으로 미니 화상통화 창 열기
        const pipWindow = window.open('', 'videoChatPip', 
            'width=320,height=400,resizable=yes,scrollbars=no,status=no,toolbar=no,menubar=no,location=no'
        );

        if (!pipWindow) {
            $c.win.alert('팝업이 차단되었습니다. 팝업을 허용해주세요.');
            return;
        }

        // PIP 창의 HTML 구성
        const pipHtml = `
            <!DOCTYPE html>
            <html>
            <head>
                <title>화상통화 - PIP</title>
                <style>
                    * { margin: 0; padding: 0; box-sizing: border-box; }
                    body { 
                        background: rgba(0, 0, 0, 0.9); 
                        font-family: Arial, sans-serif;
                        overflow: hidden;
                    }
                    .pip-header {
                        background: #FFB823;
                        color: white;
                        padding: 8px 12px;
                        font-size: 14px;
                        font-weight: bold;
                        display: flex;
                        justify-content: space-between;
                        align-items: center;
                    }
                    .pip-close {
                        background: none;
                        border: none;
                        color: white;
                        font-size: 18px;
                        font-weight: bold;
                        cursor: pointer;
                        padding: 0;
                        width: 20px;
                        height: 20px;
                        display: flex;
                        align-items: center;
                        justify-content: center;
                    }
                    .pip-close:hover { background: rgba(255, 255, 255, 0.2); }
                    .video-grid {
                        display: grid;
                        grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
                        grid-gap: 5px;
                        padding: 10px;
                        height: calc(100vh - 40px);
                        overflow-y: auto;
                    }
                    .video-item {
                        background: #2a2a2a;
                        border-radius: 8px;
                        overflow: hidden;
                        position: relative;
                        aspect-ratio: 16/9;
                    }
                    .video-item video {
                        width: 100%;
                        height: 100%;
                        object-fit: cover;
                    }
                    .user-name {
                        position: absolute;
                        bottom: 5px;
                        left: 5px;
                        background: rgba(0, 0, 0, 0.7);
                        color: white;
                        padding: 2px 6px;
                        border-radius: 4px;
                        font-size: 10px;
                    }
                    .no-video {
                        display: flex;
                        align-items: center;
                        justify-content: center;
                        color: #ccc;
                        font-size: 12px;
                    }
                </style>
            </head>
            <body>
                <div class="pip-header">
                    <span>화상통화 (${participantCount}명)</span>
                    <button class="pip-close" onclick="window.close()">×</button>
                </div>
                <div class="video-grid" id="pipVideoGrid">
                    ${participantCount === 0 ? '<div class="no-video">참가자가 없습니다</div>' : ''}
                </div>
            </body>
            </html>
        `;

        pipWindow.document.write(pipHtml);
        pipWindow.document.close();

        // 비디오 스트림을 PIP 창으로 복사
        if (participantCount > 0) {
            setTimeout(function() {
                scwin.cloneVideosToPopup(pipWindow);
            }, 100);
        }



    } catch (error) {

        $c.win.alert('PIP 모드 실행 중 오류가 발생했습니다.');
    }
};

// 비디오 스트림을 팝업창으로 복사
scwin.cloneVideosToPopup = function(pipWindow) {
    try {
        const pipVideoGrid = pipWindow.document.getElementById('pipVideoGrid');
        if (!pipVideoGrid) return;

        // 기존 내용 지우기
        pipVideoGrid.innerHTML = '';

        // 현재 창의 모든 비디오 요소 찾기
        const videoContainers = document.querySelectorAll('.remote-user-video');

        videoContainers.forEach(function(container, index) {
            const video = container.querySelector('video');
            const userName = container.querySelector('.remote-user-name')?.textContent || `참가자 ${index + 1}`;

            if (video && video.srcObject) {
                // PIP 창에 비디오 아이템 생성
                const videoItem = pipWindow.document.createElement('div');
                videoItem.className = 'video-item';

                const clonedVideo = pipWindow.document.createElement('video');
                clonedVideo.srcObject = video.srcObject;
                clonedVideo.autoplay = true;
                clonedVideo.muted = true;
                clonedVideo.playsInline = true;

                const userNameDiv = pipWindow.document.createElement('div');
                userNameDiv.className = 'user-name';
                userNameDiv.textContent = userName;

                videoItem.appendChild(clonedVideo);
                videoItem.appendChild(userNameDiv);
                pipVideoGrid.appendChild(videoItem);
            }
        });

        // 비디오가 없으면 메시지 표시
        if (pipVideoGrid.children.length === 0) {
            pipVideoGrid.innerHTML = '<div class="no-video">참가자가 없습니다</div>';
        }

    } catch (error) {

    }
};

// 세션 사용자 정보 로드 완료 이벤트
scwin.sbm_getUserInfo_submitdone = function(e) {
    try {


        // 세션에서 가져온 사용자 정보 확인
        var sessionUserId = dm_userInfo.get("userId");
        var sessionUserName = dm_userInfo.get("userName");
        var sessionUserImage = dm_userInfo.get("userImage");



        // 실제 로그인 사용자 정보로 업데이트
        if (sessionUserId && sessionUserName) {
            currentUser.userName = sessionUserName;

            // WebRTC 사용자 ID는 고유성을 위해 세션ID + 타임스탬프 조합 사용
            var timestamp = Date.now();
            currentUser.userId = sessionUserId + "_" + timestamp;



            // 데이터맵 업데이트
            dma_videoChat.set("userId", currentUser.userId);
            dma_videoChat.set("userName", currentUser.userName);

        } else {

            // 기본값 설정
            currentUser.userName = "익명사용자";
            dma_videoChat.set("userName", currentUser.userName);
        }

        // WebRTC 초기화 진행
        scwin.initializeWebRTCAfterUserInfo();

    } catch (error) {

        // 오류 시 기본값으로 진행
        currentUser.userName = "익명사용자";
        dma_videoChat.set("userName", currentUser.userName);
        scwin.initializeWebRTCAfterUserInfo();
    }
};

// 세션 사용자 정보 로드 실패 이벤트
scwin.sbm_getUserInfo_submiterror = function(e) {


    // 실패 시 기본값 사용
    currentUser.userName = "익명사용자";
    dma_videoChat.set("userName", currentUser.userName);

    // WebRTC 초기화 진행
    scwin.initializeWebRTCAfterUserInfo();
};

// 사용자 정보 로드 후 WebRTC 초기화
scwin.initializeWebRTCAfterUserInfo = function() {
    try {


        // Simple WebRTC 초기화
        scwin.initializeSimpleWebRTC();



        // 페이지 진입 시 자동으로 화상통화 참가
        setTimeout(() => {

            scwin.autoJoinCall();
        }, 1000);

    } catch (error) {

    }
};

// PIP 모드 설정 (UI 간소화)
scwin.setupPipMode = function() {


    try {
        // PIP 모드 플래그 설정
        window.isPipMode = true;

        // 불필요한 UI 요소들 숨기기
        const elementsToHide = [
            '.control-panel', // 컨트롤 패널
            '.chat-section', // 채팅 영역
            '.participant-list', // 참가자 목록
            '.toolbar', // 툴바
            '.header', // 헤더
            '#pipBtn' // PIP 버튼 자체
        ];

        elementsToHide.forEach(selector => {
            const elements = document.querySelectorAll(selector);
            elements.forEach(el => {
                if (el) {
                    el.style.display = 'none';
                }
            });
        });

        // 비디오 영역만 전체 화면으로 확장 (스크롤 가능)
        const videoSection = document.querySelector('.video-section');
        if (videoSection) {
            videoSection.style.cssText = `
                position: fixed !important;
                top: 0 !important;
                left: 0 !important;
                width: 100% !important;
                height: 100% !important;
                z-index: 9999 !important;
                background: #000 !important;
                overflow: auto !important;
                padding: 10px !important;
                box-sizing: border-box !important;
            `;
        }

        // 로컬 비디오 크기 조정
        const localVideo = document.getElementById('localVideo');
        if (localVideo) {
            localVideo.style.cssText = `
                position: absolute !important;
                bottom: 10px !important;
                right: 10px !important;
                width: 80px !important;
                height: 60px !important;
                z-index: 10000 !important;
                border-radius: 5px !important;
            `;
        }

        // body 스크롤 허용
        document.body.style.overflow = 'auto';
        document.documentElement.style.overflow = 'auto';

    } catch (error) {
    }
};

